-- ============================================================================
-- 06_achjuman.sql   |   Exam type: أدمغة  (code = 'ACHJUMAN')
-- ----------------------------------------------------------------------------
-- 5 sections x 20 questions x 4 choices (1 correct) = 100 questions / 400 choices
-- Content is Arabic.
--
-- Target: PostgreSQL. Tables per prisma/schema.prisma
--   exam_types (id uuid, name text, code varchar(100) UNIQUE)
--   sections   (id uuid, name text, exam_type_id uuid -> exam_types.id)
--   questions  (id uuid, content text, explanation text, created_at, section_id uuid)
--   choices    (id uuid, content text, is_correct bool, question_id uuid)
--
-- IDEMPOTENT: safe to re-run. No hard-coded UUIDs, so it works alongside rows
-- already created by the Prisma seeder (src/seeds/seed.ts). Rows are matched on
-- natural keys (exam_types.code, sections.name, questions.content, choices.content).
--
-- NOTE: the mobile app selects exam types and sections by NAME substring, not by
-- code -- see src/app/{verbal,quantitative,achievement,step}.tsx. Changing a
-- name below can make a section stop showing up on its screen.
--
-- Run:  psql "$DATABASE_URL" -f 06_achjuman.sql
-- ============================================================================

BEGIN;

-- ----------------------------------------------------------------------------
-- 1) EXAM TYPE
-- ----------------------------------------------------------------------------
-- NOTE: every id is supplied explicitly. prisma/schema.prisma declares the ids as
-- @default(uuid()), which Prisma resolves in the client, so the DDL has no column
-- DEFAULT and a raw INSERT that omits id fails with SQLSTATE 23502.
-- gen_random_uuid() is built in from PostgreSQL 13 on, so no extension is needed.
INSERT INTO exam_types (id, name, code)
SELECT gen_random_uuid(), v.name, v.code
FROM (VALUES ('أدمغة', 'ACHJUMAN')) AS v(name, code)
WHERE NOT EXISTS (
  SELECT 1 FROM exam_types et WHERE et.code = v.code
);

-- ----------------------------------------------------------------------------
-- 2) SECTIONS
-- ----------------------------------------------------------------------------
INSERT INTO sections (id, name, exam_type_id)
SELECT gen_random_uuid(), v.name, et.id
FROM (VALUES
  ('الفيزياء' , 1),
  ('الكيمياء' , 2),
  ('الأحياء'  , 3),
  ('الإحصاء'  , 4),
  ('الاستدلال', 5)
) AS v(name, ord)
JOIN exam_types et ON et.code = 'ACHJUMAN'
WHERE NOT EXISTS (
  SELECT 1 FROM sections s
  WHERE s.exam_type_id = et.id AND s.name = v.name
);

-- ============================================================================
-- 3) QUESTIONS + CHOICES
--    Repeated per section. `sec` resolves the section id from its natural key.
-- ============================================================================

-- ---------------------------------------------------------------- الفيزياء ---
WITH sec AS (
  SELECT s.id FROM sections s
  JOIN exam_types et ON et.id = s.exam_type_id
  WHERE et.code = 'ACHJUMAN' AND s.name = 'الفيزياء'
)
INSERT INTO questions (id, content, explanation, section_id)
SELECT gen_random_uuid(), v.content, v.expl, sec.id
FROM (VALUES
  ('وحدة قياس القوة في النظام الدولي هي:'                      , 'وحدة القوة هي النيوتن.'                                                            , 1),
  ('وحدة قياس الشغل في النظام الدولي هي:'                      , 'وحدة الشغل هي الجول، وتساوي نيوتن في المتر.'                                       , 2),
  ('وحدة قياس القدرة في النظام الدولي هي:'                     , 'وحدة القدرة هي الواط، وتساوي جول في الثانية.'                                      , 3),
  ('الشغل يساوي:'                                              , 'الشغل = القوة × الإزاحة في اتجاه القوة.'                                           , 4),
  ('القدرة تساوي:'                                             , 'القدرة = الشغل ÷ الزمن.'                                                           , 5),
  ('الوزن يساوي:'                                              , 'الوزن = الكتلة × تسارع الجاذبية، وهو ٩٫٨ في الوحدات المعتادة.'                     , 6),
  ('الضغط يساوي:'                                              , 'الضغط = القوة ÷ مساحة السطح.'                                                      , 7),
  ('تناسب الطاقة الحركية مع:'                                  , 'الطاقة الحركية تتناسب مع مربع السرعة، فمضاعفة السرعة تضاعف الطاقة أربع مرات.'      , 8),
  ('ماذا يحدث للطاقة الحركية عند مضاعفة السرعة؟'               , 'الطاقة الحركية تتناسب مع مربع السرعة، فتتضاعف السرعة مرتين فتزيد الطاقة أربع مرات.', 9),
  ('الزخم يساوي:'                                              , 'الزخم = الكتلة × السرعة.'                                                          , 10),
  ('نص قانون نيوتن الثالث هو:'                                 , 'لكل فعل ردة فعل مساوية له ولاتساويه في الاتجاه المعاكس.'                           , 11),
  ('إذا كان الجسم متسارع الحركة فإن محصيلة القوى المؤثرة عليه:', 'وجود تسارع يعني أن محصيلة القوى ليست صفرا.'                                        , 12),
  ('تغير اتجاه شعاع الضوء عند انتقاله من وسط إلى آخر يسمّى:'   , 'انكسار الضوء هو تغير اتجاه الشعاع عند مروره من وسط إلى وسط آخر.'                   , 13),
  ('العدسة المحدبة تسمّى كذلك:'                                , 'العدسة المحدبة مجمعة لأنها تجمع الأشعة المتوازية في نقطة واحدة.'                   , 14),
  ('لماذا لا نسمع الصوت في الفضاء؟'                            , 'الصوت وسيلة ميكانيكية تحتاج وسطا ماديا ينتقل فيه، والفراغ خال من المادة.'          , 15),
  ('سرعة الصوت في الهواء تتأثر بـ:'                            , 'سرعة الصوت تعتمد على نوع الوسط وحرارته.'                                           , 16),
  ('قانون أوم ينص على أن:'                                     , 'شدة التيار = فرق الجهد ÷ المقاومة.'                                                , 17),
  ('المقاومة في الدارة الكهربائية وحدتها:'                     , 'وحدة المقاومة هي الأوم.'                                                           , 18),
  ('المادة المستخدمة في مقاومات التسخين هي:'                   , 'المادة المعدنية مثل النحاس تنقل الكهرباء وتسخن مع مرور التيار.'                    , 19),
  ('كفاءة أي جهاز تساوي:'                                      , 'الكفاءة = القدرة المفيدة ÷ القدرة المستهلكة، وتكون أقل من مائة في المئة.'          , 20)
) AS v(content, expl, ord)
CROSS JOIN sec
WHERE NOT EXISTS (
  SELECT 1 FROM questions q WHERE q.section_id = sec.id AND q.content = v.content
);

