  ('الجسيم الذي يحمل شحنة موجبة في الذرة هو:'                      , 'البروتون يحمل شحنة موجبة، والإلكترون شحنة سالبة، والنيوترون محايد.'     , 2),
  ('عدد البروتونات في ذرة العنصر يسمّى:'                           , 'العدد الذري هو عدد البروتونات، وهو الذي يحدد هوية العنصر.'              , 3),
  ('الفرق بين ذرتي لعنصر واحد في العدد الكتلي بسبب اختلاف:'        , 'اختلاف النيوترونات هو سبب اختلاف الكتلة بين ذرات العنصر نفسه.'          , 4),
  ('المادة التي تتكون من أكثر من نوع من العناصر تسمّى:'            , 'المادة المختلطة مثل الماء تتكون من عدة عناصر مختلفة معا.'               , 5),
  ('في التفاعل الكيميائي:'                                         , 'في التفاعل الكيميائي تتكون مواد جديدة من مواد قديمة.'                   , 6),
  ('الغاز الذي تتنفسه الحيتان من الماء هو:'                        , 'الحيتان تتنفس الأكسجين المذاب في الماء عبر فتحات في رأسها.'             , 7),
  ('الهواء يتكون أساسا من غازين هما:'                              , 'النيتروجين والأكسجين يشكلان معظم حجم الهواء.'                           , 8),
  ('الجسم الذي يسرّع التفاعل دون أن يستهلك في نهاية التفاعل يسمّى:', 'الحافز يسرّع التفاعل ويبقى كما هو بعد انتهاء التفاعل.'                  , 9),
  ('المادة التي تذوب في الماء وتكوّن محلولا تسمّى:'                , 'الذابة تذوب في المذيبة، والمذيبة هي السائل الذي تذوب فيه الذابة.'       , 10),
  ('المحلول الذي نسبة المذيبة فيه إلى الذابة أقل من واحد يسمّى:'   , 'المحلول المخفف تكون نسبة المذيبة فيه أقل من نسبة الذابة.'               , 11),
  ('المحلول الذي لا يذوب فيه ذاب أكثر من مقداره يسمّى:'            , 'المحلول المشبع هو الذي الذابة فيه بلغت حدها الأقصى عند نفس الحرارة.'    , 12),
  ('عند تسخين الماء فإن جزيئاته:'                                  , 'التسخين يزيد الطاقة الحركية فتتحرك جزيئات الماء بسرعة أكبر حتى تتبخر.'  , 13),
  ('عند تبريد الماء حتى الصفر فإن:'                                , 'عند التبريد إلى الصفر يبقى الماء سائلا، وعند الصفر بالضبط يبدأ بالتجمد.', 14),
  ('انتقال الماء من السائل إلى الغاز فإن ذلك يسمّى:'               , 'التبخر هو انتقال السائل إلى الغاز، والاندفاع المعاكس هو التكاثف.'       , 15),
  ('انتقال الغاز إلى السائل يسمّى:'                                , 'التكاثف هو انتقال الغاز إلى السائل، مثل قطرات الماء على الزجاج البارد.' , 16),
  ('المادة الصلبة التي تتحول إلى سائل بالتسخين يسمّى:'             , 'الانصهار هو تحويل المادة الصلبة إلى سائل بارتفاع الحرارة.'              , 17),
  ('التفاعل الذي يرافقه انطلاق حرارة يسمّى:'                       , 'التفاعل الطارد للحرارة يكون صافي الطاقة فيه سالبا، فيطلق حرارة للمحيط.' , 18),
  ('التفاعل الذي يمتص حرارة من المحيط يسمّى:'                      , 'التفاعل الماص للحرارة يسحب حرارة من المحيط فيبرد ما حوله.'              , 19),
  ('الفلزات بصفة عامة:'                                            , 'الفلزات موصلة للحرارة والكهرباء وقابلة للطرق والسحب، ولها بريق معدني.'  , 20)
) AS v(content, expl, ord)
CROSS JOIN sec
WHERE NOT EXISTS (
  SELECT 1 FROM questions q WHERE q.section_id = sec.id AND q.content = v.content
);

