-- ---------------------------------------------------------------- الأحياء ---
WITH sec AS (
  SELECT s.id FROM sections s
  JOIN exam_types et ON et.id = s.exam_type_id
  WHERE et.code = 'ACHJUMAN' AND s.name = 'الأحياء'
)
INSERT INTO questions (id, content, explanation, section_id)
SELECT gen_random_uuid(), v.content, v.expl, sec.id
FROM (VALUES
  ('الوحدة البنيوية والوظيفية الأساسية في الكائن الحي هي:'             , 'الخلية هي وحدة البناء في جميع الكائنات الحية.'                             , 1),
  ('الجزء الذي يتحكم في أنشطة الخلية ويحمل المادة الوراثية هو:'        , 'النواة تتحكم في أنشطة الخلية وتحمل المادة الوراثية.'                       , 2),
  ('العضوية المسؤولة عن إنتاج الطاقة داخل الخلية هي:'                  , 'الميتوكندريا هي مصنع الطاقة في الخلية.'                                    , 3),
  ('العملية التي تصنع فيها النباتات غذاءها باستخدام ضوء الشمس تسمّى:'  , 'التركيب الضوئي هو تصنيع النبات لغذائه من الشمس والماء وثاني أكسيد الكربون.', 4),
  ('الغاز الذي تمتصه النباتات في التركيب الضوئي هو:'                   , 'تمتص النباتات ثاني أكسيد الكربون لتصنع به غذاءها.'                         , 5),
  ('في عملية التنفس الخلوي:'                                           , 'في التنفس الخلوي تحرر الخلية الطاقة من الغذاء باستخدام الأكسجين.'          , 6),
  ('العضو الذي يضخ الدم إلى كل أنحاء الجسم هو:'                        , 'القلب يضخ الدم إلى أنحاء الجسم، والأوعية تنقله.'                           , 7),
  ('الأكسجين الذي يتنفسه الإنسان يصل إلى الدم عبر:'                    , 'الأكسجين يمر من الرئتين إلى الدم عبر جدران الحويصلات الشعرية.'             , 8),
  ('العضلة التي تتحكم في دخول الهواء إلى الرئتين هي:'                  , 'الحجاب الحاجز ينقبض ويرتخي ويسحب الهواء إلى الرئتين.'                      , 9),
  ('الخليتان اللتان تتكونان من الأم تختلفان عنها في:'                  , 'الخلية الأم تنتج خلايا لاجينية تحمل صفات الأم الوراثية.'                   , 10),
  ('العامل الذي يحمل الصفات الوراثية من الأبوين إلى الأبناء هو:'       , 'الجينات حاملة الصفات الوراثية وتنقل من الأبوين إلى الأبناء.'               , 11),
  ('الصفة التي لا تظهر في الأبناء إلا إذا اجتمعت صفتان متنحيتان تسمّى:', 'الصفة المتنحية لا تظهر إلا عند اجتماع صفتين متنحيتين.'                     , 12),
  ('الكائن الحي الذي يتكون من خلية واحدة هو:'                          , 'الأميبا مخلوق حي يتكون من خلية واحدة.'                                     , 13),
  ('علاقة الطفيليات بضيفها هي علاقة:'                                  , 'الطفيلي يستفيد من المضيف ويضره، فبينهما علاقة تتبعية.'                     , 14),
  ('أي مما يلي من صفات النباتات:'                                      , 'النباتات ذاتية التغذية تصنع غذاءها بالضوء، ولها جذر وساق وأوراق.'          , 15),
  ('النباتات تمتص الماء والأملاح عن طريق:'                             , 'تمتص النباتات الماء والأملاح عن طريق الجذور من التربة.'                    , 16),
  ('خروج الماء الزائد من النبات على شكل بخار يسمّى:'                   , 'النتح هو خروج الماء الزائد من النبات على شكل بخار من الثغور.'              , 17),
  ('المستوى الذي تتشابه فيه صفات أفراده ولا يظهر بينها اختلاف يسمّى:'  , 'أفراد النوع الواحد متشابهة في صفاتها، بخلاف أفراد الأنواع المختلفة.'       , 18),
  ('تنوع الكائنات الحي في الطبيعة يعني:'                               , 'التنوع الحيوي يعني اختلاف الكائنات الحية وتنوعها في الخلق.'                , 19),
  ('البيئة التي يعيش فيها الكائن الحي تؤثر في:'                        , 'البيئة تؤثر في صفات الكائن الحي وفي سلوكه ونموه.'                          , 20)
) AS v(content, expl, ord)
CROSS JOIN sec
WHERE NOT EXISTS (
  SELECT 1 FROM questions q WHERE q.section_id = sec.id AND q.content = v.content
);

