  SELECT 1 FROM choices c WHERE c.question_id = q.id AND c.content = v.content
);

-- ---------------------------------------------------------------- الإحصاء ---
WITH sec AS (
  SELECT s.id FROM sections s
  JOIN exam_types et ON et.id = s.exam_type_id
  WHERE et.code = 'ACHJUMAN' AND s.name = 'الإحصاء'
)
INSERT INTO questions (id, content, explanation, section_id)
SELECT gen_random_uuid(), v.content, v.expl, sec.id
FROM (VALUES
  ('مجموع درجات ٥ طلاب هو ٢٥٠. ما متوسط درجاتهم؟'                       , 'المتوسط = ٢٥٠ ÷ ٥ = ٥٠ درجة.'                                               , 1),
  ('متوسط العددين ١٠ و ٢٠ يساوي:'                                       , 'المتوسط = (١٠ + ٢٠) ÷ ٢ = ١٥.'                                              , 2),
  ('الوسيط لمجموعة ٤ و ٨ و ٢ و ٦ و ١٠ هو:'                              , 'بعد الترتيب: ٢ و ٤ و ٦ و ٨ و ١٠، فالوسيط هو ٦.'                             , 3),
  ('مدى الأعداد ١٥ و ٧ و ٢٣ و ٩ يساوي:'                                 , 'المدى = ٢٣ − ٧ = ١٦.'                                                       , 4),
  ('القيمة الأكثر تكرارا في مجموعة بيانات تسمّى:'                       , 'المنوال هو القيمة الأكثر تكرارا في مجموعة البيانات.'                        , 5),
  ('إذا كانت قيم مجموعة ٢ و ٤ و ٦ و ٨ و ١٠، فإن المتوسط يساوي:'         , 'مجموع القيم = ٣٠، وعددها ٥، فيكون المتوسط = ٦.'                             , 6),
  ('عند زيادة جميع قيم مجموعة بخمسة، فإن المتوسط:'                      , 'زيادة كل قيمة بخمسة يزيد المتوسط بخمسة.'                                    , 7),
  ('عند ضرب جميع قيم مجموعة في ثلاثة، فإن المدى:'                       , 'ضرب القيم في ثلاثة يضرب المدى في ثلاثة.'                                    , 8),
  ('احتمال وقوع حدث مؤكد يساوي:'                                        , 'الحدث المؤكد احتمال وقوعه واحد أي مائة في المئة.'                           , 9),
  ('عند رمي نرد، احتمال الحصول على عدد زوجي يساوي:'                     , 'الأعداد الزوجية هي ٢ و ٤ و ٦ من ٦ أوجه، فالنسبة ثلاثة من ستة أي نصف.'       , 10),
  ('عند رمي نرد، احتمال الحصول على العدد ٧ يساوي:'                      , 'الوجه السابع واحد من ستة أوجه، فالنسبة واحد من ستة.'                        , 11),
  ('مجموع احتمالات كل النتائج الممكنة في تجربة عشوائية يساوي:'          , 'مجموع احتمالات النتائج الممكنة يساوي واحدا.'                                , 12),
  ('في رمي نرد، عدد النتائج الممكنة يساوي:'                             , 'للنرد ستة أوجه، فيها ست نتائج ممكنة.'                                       , 13),
  ('في رمي عملتين، كم عدد النتائج الممكنة؟'                             , 'لكل عملة وجهان، فيكون عدد النتائج الممكنة ٢ × ٢ = ٤.'                       , 14),
  ('إذا كان عدد الذكور ٦ والإناث ٤، فما نسبة الإناث إلى المجموع؟'       , 'المجموع عشرة، ونسبة الإناث أربعة من عشرة أي ثلثان.'                         , 15),
  ('في جدول، تكرار فئة ١٠ وتكرار فئة أخرى ١٥. أي الفئتين أكثر؟'         , 'الفئة ذات التكرار ١٥ هي الأكثر.'                                            , 16),
  ('الاحتمال المكمّل لحدث ما هو:'                                       , 'الاحتمال المكمّل هو احتمال ألا يقع الحدث، ومجموعه مع الاحتمال يساوي واحدا.' , 17),
  ('كم درجة لكل زاوية في مثلث متساوي الأضلاع؟'                          , 'مجموع زوايا المثلث ١٨٠، ومتساوي الأضلاع زواياه متساوية، فتكون ٦٠ لكل زاوية.', 18),
  ('إذا كان عدد الطلاب ٤٠ ونسبة الناجحين ٢٥ في المئة، فكم عدد الناجحين؟', '٢٥ في المئة من ٤٠ = ٤٠ × ٢٥ ÷ ١٠٠ = ١٠ طلاب.'                               , 19),
  ('أي مما يلي مثال على البيانات النوعية:'                              , 'البيانات النوعية تصف صفة لا مقدار، مثل اللون أو الجنسية.'                   , 20)
) AS v(content, expl, ord)
CROSS JOIN sec
WHERE NOT EXISTS (
  SELECT 1 FROM questions q WHERE q.section_id = sec.id AND q.content = v.content
);

