-- ---------------------------------------------------------------- الاستدلال ---
WITH sec AS (
  SELECT s.id FROM sections s
  JOIN exam_types et ON et.id = s.exam_type_id
  WHERE et.code = 'ACHJUMAN' AND s.name = 'الاستدلال'
)
INSERT INTO questions (id, content, explanation, section_id)
SELECT gen_random_uuid(), v.content, v.expl, sec.id
FROM (VALUES
  ('كل الطلاب المجيدين حصلوا على الجائزة. أحمد مجيد. فماذا نستنتج؟'                   , 'الاستنتاج ينتقل من القاعدة العامة إلى الحالة الخاصة، فأحمد حصل على الجائزة.', 1),
  ('لا يوجد طالب كسول يحصل على درجة كاملة. خالد لم يحصل على درجة كاملة. فماذا نستنتج؟', 'نفي النفي يعني الإيجاب، فخالد ليس كسولا.'                                   , 2),
  ('إذا كان المربع شكلا رباعيا، والشكل الرباعي له أربعة أضلاع. فالمربع له:'           , 'الخاصية تخص المحسوب من العام، فالمربع له أربعة أضلاع.'                      , 3),
  ('كل الطيور تحلق. والسنجاب لا يحلق. فماذا نستنتج؟'                                  , 'من نفي الخاصية نفي للعموم، فما لا يحلق ليس طائرا.'                          , 4),
  ('المتوالية ٢ و ٤ و ٦ و ٨. الحد التالي هو:'                                         , 'المتوالية تزيد اثنين في كل حد، فالحد التالي عشرة.'                          , 5),
  ('المتوالية ١ و ٣ و ٩ و ٢٧. الحد التالي هو:'                                        , 'كل حد فيه ثلاثة أمثال ما قبله، فبعد ٢٧ يأتي ٨١.'                            , 6),
  ('المتوالية ١٠ و ٧ و ٤ و ١. الحد التالي هو:'                                        , 'المتوالية تنقص ثلاثة في كل حد، فبعد ١ يأتي ناقص اثنين.'                     , 7),
  ('المتوالية ١ و ٢ و ٤ و ٨. الحد التالي هو:'                                         , 'كل حد فيه ضعف ما قبله، فبعد ٨ يأتي ١٦.'                                     , 8),
  ('إذا كان أ يساوي ب، وب يساوي ٣. فقيمة أ تساوي:'                                    , 'بالانتقال بالتساوي تكون قيمة أ ثلاثة.'                                      , 9),
  ('إذا كان س يساوي ٢ مضروبا في ٣، و٣ يساوي ١ زائد ٢. فقيمة س تساوي:'                 , '٣ تساوي ٣، فس يساوي ٢ × ٣ = ٦.'                                             , 10),
  ('ما المقصود بالاستدلال الاستقرائي؟'                                                , 'الاستدلال الاستقرائي ينتقل من ملاحظات فردية إلى قاعدة عامة.'                , 11),
  ('ما المقصود بالاستدلال الاستنباطي؟'                                                , 'الاستدلال الاستنباطي ينتقل من القاعدة العامة إلى الحالات الخاصة.'           , 12),
  ('ما الفرق بين الاستدلال الصحيح والاستدلال غير الصحيح؟'                             , 'الاستدلال الصحيح يتبع قواعد المنطق، وغير الصحيح يخالفها.'                   , 13),
  ('ما معنى النفي في المنطق؟'                                                         , 'النفي هو نفي الحكم أو نفي لفظه، مثل: لم يحضر، وليس حاضرا.'                  , 14),
  ('ما المقصود بالمفارقة في الاستدلال؟'                                               , 'المفارقة نتيجة تبدو غير متوقعة لكنها صحيحة في الواقع.'                      , 15),
  ('ما المقصود بالجدل في الاستدلال؟'                                                  , 'الجدل هو تبادل رأي بين اثنين باحترام، يثبت كل منهما وجهة نظره.'             , 16),
  ('ما المقصود بالتسلسل في الاستدلال؟'                                                , 'التسلسل هو ترتيب الوقائع زمنيا من الأسبق إلى الأحدث.'                       , 17),
  ('في المنطق، إذا كانت المقدمة خاطئة فالاستنتاج:'                                    , 'المقدمة الخاطئة لا تقود إلى نتيجة مضمونة، فالاستنتاج غير مضمون الصحة.'      , 18),
  ('ما المقصود باحتمال المقلوب في الاستدلال؟'                                         , 'احتمال المقلوب هو أن أثر السبب يعود فيؤثر في سببه لا في نتيجته.'            , 19),
  ('ما أفضل طريقة لزيادة صدق الاستدلال؟'                                              , 'الاستدلال يصدق إذا قوم على أدلة صحيحة ولم يعتمد على العاطفة.'               , 20)
) AS v(content, expl, ord)
CROSS JOIN sec
WHERE NOT EXISTS (
  SELECT 1 FROM questions q WHERE q.section_id = sec.id AND q.content = v.content
);

